from .repository import put_contact, contact_exists, insert_contact, update_contact_name

_ROW_FIELDS = frozenset({"email", "name"})

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _clean_row(row):
    if not isinstance(row, dict):
        raise ValueError("row must be an object")
    if set(row) != _ROW_FIELDS:
        raise ValueError("row must have exactly the fields email and name")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError("email and name must be strings")
    email = email.strip()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError("email must contain exactly one @")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError("email must have nonempty sides around @")
    if any(ch.isspace() for ch in email):
        raise ValueError("email must not contain whitespace")
    if not name:
        raise ValueError("name must not be empty")
    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")
    batch = []
    seen = set()
    for row in rows:
        email, name = _clean_row(row)
        if email in seen:
            raise ValueError("duplicate email in batch")
        seen.add(email)
        batch.append((email, name))

    inserted = updated = 0
    connection.execute("BEGIN IMMEDIATE")
    try:
        for email, name in batch:
            if contact_exists(connection, email):
                update_contact_name(connection, email, name)
                updated += 1
            else:
                insert_contact(connection, email, name)
                inserted += 1
        connection.commit()
    except BaseException:
        connection.rollback()
        raise
    return {"inserted": inserted, "updated": updated}
